async function updateBuildInfo(){try{const e=await(await fetch("https://api.github.com/repos/infinotiver/infinotiver.github.io/commits")).json(),n=e[0]?.sha.substring(0,7),i=e[0]?.commit.author.date,o=new Date(i).toLocaleString("en-US",{year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit",timeZoneName:"short"});console.log(o),document.getElementById("last-commit").textContent=n||"N/A",document.getElementById("last-update").textContent=o||"N/A"}catch(t){console.error("Error fetching GitHub data:",t)}}updateBuildInfo();
